components.css:
.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; min-height: 2.25rem; padding: 0.5rem 1rem; border: none; border-radius: var(--radius-md, calc(var(--radius, 0.75rem) - 2px)); background: var(--primary, #a4ddff); color: var(--primary-foreground, #102538); font: 500 0.875rem/1.25rem var(--fonte-texto, "DM Sans", system-ui, sans-serif); box-shadow: none; cursor: pointer; transition: all 150ms cubic-bezier(.4, 0, .2, 1); }
.ds-button-primary:hover { background: color-mix(in oklab, var(--primary, #a4ddff) 90%, transparent); }
.ds-button-primary:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary, #a4ddff) 50%, transparent); }
.ds-button-primary:disabled { opacity: 0.5; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .ds-button-primary { transition-duration: 0.01ms; } }

.ds-button-outline { display: inline-flex; align-items: center; justify-content: center; min-height: 2.25rem; padding: 0.5rem 1rem; border: 1px solid currentColor; border-radius: var(--radius-md, calc(var(--radius, 0.75rem) - 2px)); background: var(--background, #0e141e); color: var(--foreground, #f0f4fa); font: 500 0.875rem/1.25rem var(--fonte-texto, "DM Sans", system-ui, sans-serif); box-shadow: 0 1px 2px 0 #0000000d; cursor: pointer; transition: all 150ms cubic-bezier(.4, 0, .2, 1); }
.ds-button-outline:hover { background: var(--secondary, #202d3d); }
.ds-button-outline:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary, #a4ddff) 50%, transparent); }
.ds-button-outline:disabled { opacity: 0.5; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .ds-button-outline { transition-duration: 0.01ms; } }

.ds-button-ghost { display: inline-flex; align-items: center; justify-content: center; min-height: 2.25rem; padding: 0.5rem 1rem; border: none; border-radius: var(--radius-md, calc(var(--radius, 0.75rem) - 2px)); background: transparent; color: var(--foreground, #f0f4fa); font: 500 0.875rem/1.25rem var(--fonte-texto, "DM Sans", system-ui, sans-serif); box-shadow: none; cursor: pointer; transition: all 150ms cubic-bezier(.4, 0, .2, 1); }
.ds-button-ghost:hover { background: var(--secondary, #202d3d); }
.ds-button-ghost:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary, #a4ddff) 50%, transparent); }
.ds-button-ghost:disabled { opacity: 0.5; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .ds-button-ghost { transition-duration: 0.01ms; } }

.ds-input-label { display: grid; gap: 0.35rem; color: var(--foreground, #f0f4fa); font: 650 0.93rem/1.55 var(--fonte-texto, "DM Sans", system-ui, sans-serif); }
.ds-input-label input { box-sizing: border-box; width: 100%; min-height: 2.9rem; padding: 0.25rem 0.75rem; border: 1px solid var(--input, #64768b); border-radius: var(--radius-md, calc(var(--radius, 0.75rem) - 2px)); background: var(--background, #0e141e); color: var(--foreground, #f0f4fa); caret-color: var(--primary, #a4ddff); font: 400 1rem/1.55 var(--fonte-texto, "DM Sans", system-ui, sans-serif); box-shadow: 0 1px 2px 0 #0000000d; transition: color 150ms cubic-bezier(.4, 0, .2, 1), box-shadow 150ms cubic-bezier(.4, 0, .2, 1); }
.ds-input-label input:focus-visible { border-color: var(--primary, #a4ddff); outline: none; box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary, #a4ddff) 50%, transparent); }
.ds-input-label input[aria-invalid="true"] { border-color: var(--destructive, #ffb4b8); }
.ds-input-label input:disabled { cursor: not-allowed; opacity: 0.5; }
@media (prefers-reduced-motion: reduce) { .ds-input-label input { transition-duration: 0.01ms; } }

.ds-nav { display: flex; flex-wrap: wrap; gap: 0 1.5rem; align-items: center; padding-inline: 0.75rem; border-bottom: 1px solid var(--border, #303c4d); background: var(--background, #0e141e); color: var(--muted-foreground, #b1bed0); font: 650 0.93rem/1.55 var(--fonte-texto, "DM Sans", system-ui, sans-serif); }
.ds-nav a { position: relative; display: inline-flex; min-height: 4.5rem; align-items: center; color: inherit; text-decoration: none; }
.ds-nav a:hover, .ds-nav [aria-current="page"] { color: var(--primary, #a4ddff); }
.ds-nav a:focus-visible { outline: 2px solid var(--primary, #a4ddff); outline-offset: 3px; }
.ds-nav [aria-current="page"]::after { position: absolute; inset: auto 0 -1px; height: 2px; content: ""; background: var(--primary, #a4ddff); }

.ds-estilo { display: inline-flex; align-items: center; gap: 0.375rem; min-height: 2.5rem; padding-inline: 0.625rem; border: 1px solid currentColor; border-radius: var(--radius-md, calc(var(--radius, 0.75rem) - 2px)); background: var(--background, #0e141e); color: var(--foreground, #f0f4fa); font: 500 0.875rem/1.25rem var(--fonte-texto, "DM Sans", system-ui, sans-serif); text-decoration: none; box-shadow: 0 1px 2px 0 #0000000d; transition: all 150ms cubic-bezier(.4, 0, .2, 1); }
.ds-estilo:hover { background: var(--secondary, #202d3d); }
.ds-estilo:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in oklab, var(--primary, #a4ddff) 50%, transparent); }
@media (prefers-reduced-motion: reduce) { .ds-estilo { transition-duration: 0.01ms; } }

.ds-nota { display: flex; flex-direction: column; align-items: start; gap: 0.6rem; padding: clamp(1rem, 3vw, 1.55rem); border: 1px solid var(--border, #303c4d); border-radius: var(--radius-xl, calc(var(--radius, 0.75rem) + 4px)); background: var(--card, #171f2c); color: var(--foreground, #f0f4fa); font: 400 1rem/1.55 var(--fonte-texto, "DM Sans", system-ui, sans-serif); }
.ds-nota h2 { display: flex; gap: 0.55rem; align-items: center; margin: 0; font: 700 clamp(1.45rem, 3.25vw, 2rem)/1.08 var(--fonte-titulo, "Barlow Condensed", "Arial Narrow", sans-serif); letter-spacing: -0.015em; }
.ds-nota svg { flex: none; color: var(--primary, #a4ddff); }
.ds-nota p { margin: 0; color: var(--muted-foreground, #b1bed0); }
.ds-nota strong { color: var(--foreground, #f0f4fa); font-variant-numeric: tabular-nums; }

.ds-destaque { display: flex; max-width: 24rem; align-items: center; justify-content: space-between; gap: 1.2rem; padding: 0.9rem 1.05rem; border: 1px solid #54687a; border-radius: var(--radius, 0.75rem); background: #162333; color: var(--foreground, #f0f4fa); text-decoration: none; transition: background 180ms ease-out, border-color 180ms ease-out; }
.ds-destaque:hover, .ds-destaque:focus-visible { border-color: var(--primary, #a4ddff); background: var(--secondary, #202d3d); }
.ds-destaque:focus-visible { outline: 2px solid var(--primary, #a4ddff); outline-offset: 3px; }
.ds-destaque strong { font: 700 clamp(1.65rem, 3vw, 2.3rem)/1 var(--fonte-titulo, "Barlow Condensed", "Arial Narrow", sans-serif); }
.ds-destaque p { margin: 0.35rem 0 0; color: var(--muted-foreground, #b1bed0); font: 400 0.875rem/1.55 var(--fonte-texto, "DM Sans", system-ui, sans-serif); }
.ds-destaque span { display: grid; width: 2.5rem; height: 2.5rem; flex: 0 0 2.5rem; place-items: center; border: 1px solid #54687a; border-radius: 50%; color: var(--primary, #a4ddff); }
@media (prefers-reduced-motion: reduce) { .ds-destaque { transition-duration: 0.01ms; } }
